// End-to-end encryption, ported from OpenTodo's web/src/lib/crypto.ts and
// e2eeEnvelope.ts (OpenSpec `e2ee`, design D1/D3). Pinned by the shared
// known-answer vectors test/vectors/e2ee.vectors.json, generated by the Go
// server (internal/e2ee/vectors_test.go) and verified by the web app too.
//
// Key hierarchy (all client-side):
//   account key (DEK)   AES-256-GCM, 256 random bits
//   passphrase key      PBKDF2-HMAC-SHA-256(passphrase NFC, 16-byte salt,
//                       600,000) -> AES-KW-256
//   recovery key        256 random bits, shown once as 56 base32 characters
//                       (52 key + 4 checksum), HKDF-SHA-256 -> AES-KW-256
// The DEK is wrapped (AES-KW, RFC 3394) under both; only the wrapped blobs and
// the derivation parameters reach the server (the key record).
//
// Content value format, carried as an ordinary string through the op log:
//   "enc:v1:" + base64url(nonce(12) || AES-256-GCM(utf8(plaintext)) incl. tag)
//   additional authenticated data = utf8(entity + "\0" + entityId + "\0" + field)

import 'dart:convert';
import 'dart:math';
import 'dart:typed_data';

import 'package:pointycastle/export.dart';
import 'package:unorm_dart/unorm_dart.dart' as unorm;

import 'schema_generated.dart';

const String prefix = 'enc:';
const String prefixV1 = 'enc:v1:';
const int kdfPbkdf2Sha256 = 1;
const int pbkdf2Iterations = 600000;
const int minPassphraseLength = 12;
const int acceptedIterationsMin = pbkdf2Iterations;
const int acceptedIterationsMax = 10000000;

/// The range checkRecordParams applies. Mutable only so tests can derive keys
/// quickly (the same hook as ITERATION_LIMITS in web/src/lib/crypto.ts).
int iterationLimitMin = acceptedIterationsMin;
int iterationLimitMax = acceptedIterationsMax;

/// Largest plaintext (UTF-8 bytes) a content field may hold on an encrypted
/// account: its envelope stays under the server's 64 KiB value limit.
const int maxPlaintextBytes = 48000;

const int _nonceBytes = 12;
const String _recoveryInfo = 'opentodo/e2ee/recovery-kek/v1';
const String _base32Alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
final RegExp _envelopeRe = RegExp(r'^enc:v[0-9]+:[A-Za-z0-9_-]{38,}$');
final RegExp _b64urlRe = RegExp(r'^[A-Za-z0-9_-]*$');
final Random _random = Random.secure();

/// A value failed to decrypt: wrong key, tampered ciphertext, or moved to
/// another field.
class DecryptError implements Exception {
  final String message;
  DecryptError([this.message = 'cannot decrypt this value']);
  @override
  String toString() => 'DecryptError: $message';
}

/// The passphrase or recovery key did not unwrap the account key.
class WrongSecretError implements Exception {
  final String message;
  WrongSecretError([this.message = 'the passphrase or recovery key is not correct']);
  @override
  String toString() => 'WrongSecretError: $message';
}

/// A recovery key was mistyped (bad length, characters or checksum).
class RecoveryKeyFormatError implements Exception {
  final String message;
  RecoveryKeyFormatError([this.message = 'this is not a valid recovery key; check for typos']);
  @override
  String toString() => 'RecoveryKeyFormatError: $message';
}

/// A key record's derivation parameters are outside what this client accepts.
class KeyRecordParamsError implements Exception {
  final int iterations;
  KeyRecordParamsError(this.iterations);
  @override
  String toString() =>
      'KeyRecordParamsError: $iterations iterations outside the accepted range';
}

// ---- encoding ----

Uint8List utf8Bytes(String s) => Uint8List.fromList(utf8.encode(s));

String b64url(Uint8List bytes) =>
    base64Url.encode(bytes).replaceAll('=', '');

Uint8List fromB64url(String s) {
  if (!_b64urlRe.hasMatch(s)) throw FormatException('not base64url');
  final pad = (4 - s.length % 4) % 4;
  return base64Url.decode(s + '=' * pad);
}

Uint8List randomBytes(int n) {
  final b = Uint8List(n);
  for (var i = 0; i < n; i++) {
    b[i] = _random.nextInt(256);
  }
  return b;
}

/// True for a string that starts like a ciphertext envelope (the server's
/// loose check).
bool isCiphertext(Object? v) => v is String && v.startsWith(prefix);

/// True for a well-formed envelope: "enc:vN:" and at least nonce + tag of
/// base64url. Stricter than isCiphertext so a title someone typed as "enc: …"
/// is still treated (and encrypted) as text.
bool isEnvelope(Object? v) => v is String && _envelopeRe.hasMatch(v);

// ---- primitives ----

Uint8List _aesGcm(Uint8List key, Uint8List nonce, Uint8List aad, Uint8List input,
    {required bool encrypt}) {
  final cipher = GCMBlockCipher(AESEngine())
    ..init(encrypt, AEADParameters(KeyParameter(key), 128, nonce, aad));
  return cipher.process(input);
}

Uint8List _aesEcbBlock(Uint8List key, Uint8List block, {required bool encrypt}) {
  final cipher = ECBBlockCipher(AESEngine())
    ..init(encrypt, KeyParameter(key));
  return cipher.process(block);
}

/// AES Key Wrap (RFC 3394), the format of Web Crypto's AES-KW.
Uint8List aesKwWrap(Uint8List kek, Uint8List key) {
  if (key.length < 16 || key.length % 8 != 0) {
    throw ArgumentError('AES-KW key must be a multiple of 8 bytes, at least 16');
  }
  final n = key.length ~/ 8;
  var a = Uint8List.fromList(List.filled(8, 0xA6));
  final r = List.generate(n, (i) => Uint8List.fromList(key.sublist(i * 8, i * 8 + 8)));
  for (var j = 0; j < 6; j++) {
    for (var i = 0; i < n; i++) {
      final block = Uint8List(16);
      block.setRange(0, 8, a);
      block.setRange(8, 16, r[i]);
      final b = _aesEcbBlock(kek, block, encrypt: true);
      a = Uint8List.fromList(b.sublist(0, 8));
      final t = n * j + i + 1;
      for (var k = 0; k < 8; k++) {
        a[7 - k] ^= (t >> (8 * k)) & 0xff;
      }
      r[i] = Uint8List.fromList(b.sublist(8, 16));
    }
  }
  return Uint8List.fromList([...a, for (final x in r) ...x]);
}

/// AES Key Unwrap (RFC 3394); throws WrongSecretError on a wrong KEK.
Uint8List aesKwUnwrap(Uint8List kek, Uint8List wrapped) {
  if (wrapped.length < 24 || wrapped.length % 8 != 0) throw WrongSecretError();
  final n = wrapped.length ~/ 8 - 1;
  var a = Uint8List.fromList(wrapped.sublist(0, 8));
  final r = List.generate(n, (i) => Uint8List.fromList(wrapped.sublist(8 + i * 8, 16 + i * 8)));
  for (var j = 5; j >= 0; j--) {
    for (var i = n - 1; i >= 0; i--) {
      final t = n * j + i + 1;
      final ax = Uint8List.fromList(a);
      for (var k = 0; k < 8; k++) {
        ax[7 - k] ^= (t >> (8 * k)) & 0xff;
      }
      final block = Uint8List(16);
      block.setRange(0, 8, ax);
      block.setRange(8, 16, r[i]);
      final b = _aesEcbBlock(kek, block, encrypt: false);
      a = Uint8List.fromList(b.sublist(0, 8));
      r[i] = Uint8List.fromList(b.sublist(8, 16));
    }
  }
  for (final byte in a) {
    if (byte != 0xA6) throw WrongSecretError();
  }
  return Uint8List.fromList([for (final x in r) ...x]);
}

Uint8List pbkdf2Sha256(Uint8List password, Uint8List salt, int iterations, int length) {
  final d = PBKDF2KeyDerivator(HMac(SHA256Digest(), 64))
    ..init(Pbkdf2Parameters(salt, iterations, length));
  return d.process(password);
}

Uint8List hkdfSha256(Uint8List ikm, Uint8List salt, Uint8List info, int length) {
  final d = HKDFKeyDerivator(SHA256Digest())
    ..init(HkdfParameters(ikm, length, salt, info));
  return d.process(Uint8List(0));
}

Uint8List sha256Bytes(Uint8List msg) =>
    Uint8List.fromList(SHA256Digest().process(msg));

// ---- keys ----

/// A fresh account key (32 random bytes).
Uint8List generateAccountKey() => randomBytes(32);

Uint8List randomSalt() => randomBytes(16);

/// The passphrase key: PBKDF2-SHA-256 of the NFC-normalized passphrase.
Uint8List derivePassphraseKey(String passphrase, Uint8List salt, int iterations) =>
    pbkdf2Sha256(utf8Bytes(unorm.nfc(passphrase)), salt, iterations, 32);

/// The recovery key's wrapping key: HKDF-SHA-256 with a fixed context, so a
/// passphrase change never touches it.
Uint8List deriveRecoveryKey(Uint8List raw) =>
    hkdfSha256(raw, Uint8List(32), utf8Bytes(_recoveryInfo), 32);

String wrapAccountKey(Uint8List dek, Uint8List kek) => b64url(aesKwWrap(kek, dek));

Uint8List unwrapAccountKey(String wrapped, Uint8List kek) =>
    aesKwUnwrap(kek, fromB64url(wrapped));

// ---- recovery key text ----

String _base32(Uint8List bytes) {
  var bits = 0, value = 0;
  final out = StringBuffer();
  for (final b in bytes) {
    value = (value << 8) | b;
    bits += 8;
    while (bits >= 5) {
      out.write(_base32Alphabet[(value >> (bits - 5)) & 31]);
      bits -= 5;
    }
  }
  if (bits > 0) out.write(_base32Alphabet[(value << (5 - bits)) & 31]);
  return out.toString();
}

Uint8List _fromBase32(String s) {
  var bits = 0, value = 0;
  final out = <int>[];
  for (final ch in s.codeUnits) {
    final v = _base32Alphabet.indexOf(String.fromCharCode(ch));
    if (v < 0) throw RecoveryKeyFormatError();
    value = ((value << 5) | v) & 0xffff;
    bits += 5;
    if (bits >= 8) {
      out.add((value >> (bits - 8)) & 0xff);
      bits -= 8;
    }
  }
  return Uint8List.fromList(out);
}

/// 20 bits of SHA-256 as four base32 characters.
String _checksum(Uint8List raw) =>
    _base32(sha256Bytes(raw).sublist(0, 3)).substring(0, 4);

/// 32 random bytes as 14 groups of four base32 characters, the last group a
/// checksum.
String formatRecoveryKey(Uint8List raw) {
  if (raw.length != 32) throw ArgumentError('a recovery key is 32 bytes');
  final text = _base32(raw) + _checksum(raw);
  final groups = <String>[];
  for (var i = 0; i < text.length; i += 4) {
    groups.add(text.substring(i, i + 4));
  }
  return groups.join('-');
}

/// Parse a typed recovery key: case, spaces and dashes are ignored and the
/// digits 0, 1 and 8 read as O, I and B. Throws RecoveryKeyFormatError on a
/// wrong length, character or checksum.
Uint8List parseRecoveryKey(String text) {
  final s = text
      .toUpperCase()
      .replaceAll(RegExp(r'[\s-]'), '')
      .replaceAll('0', 'O')
      .replaceAll('1', 'I')
      .replaceAll('8', 'B');
  if (s.length != 56) throw RecoveryKeyFormatError();
  final raw = _fromBase32(s.substring(0, 52));
  final key = raw.length > 32 ? raw.sublist(0, 32) : raw;
  if (key.length != 32 || _base32(key) != s.substring(0, 52)) {
    throw RecoveryKeyFormatError();
  }
  if (_checksum(key) != s.substring(52)) throw RecoveryKeyFormatError();
  return Uint8List.fromList(key);
}

Uint8List generateRecoveryBytes() => randomBytes(32);

// ---- key record lifecycle ----

/// What the server stores: wrapped keys and derivation parameters.
class KeyRecord {
  int version;
  int kdf;
  String salt;
  int iterations;
  String wrappedByPassphrase;
  String wrappedByRecovery;
  int? createdAt;
  int? updatedAt;

  KeyRecord({
    required this.version,
    required this.kdf,
    required this.salt,
    required this.iterations,
    required this.wrappedByPassphrase,
    required this.wrappedByRecovery,
    this.createdAt,
    this.updatedAt,
  });

  factory KeyRecord.fromJson(Map<String, dynamic> j) => KeyRecord(
        version: (j['version'] as num).toInt(),
        kdf: (j['kdf'] as num).toInt(),
        salt: j['salt'] as String,
        iterations: (j['iterations'] as num).toInt(),
        wrappedByPassphrase: j['wrappedByPassphrase'] as String,
        wrappedByRecovery: j['wrappedByRecovery'] as String,
        createdAt: (j['createdAt'] as num?)?.toInt(),
        updatedAt: (j['updatedAt'] as num?)?.toInt(),
      );

  Map<String, dynamic> toJson() => {
        'version': version,
        'kdf': kdf,
        'salt': salt,
        'iterations': iterations,
        'wrappedByPassphrase': wrappedByPassphrase,
        'wrappedByRecovery': wrappedByRecovery,
      };
}

/// Throws KeyRecordParamsError when the iteration count is out of range.
void checkRecordParams(KeyRecord record) {
  final n = record.iterations;
  if (n < iterationLimitMin || n > iterationLimitMax) {
    throw KeyRecordParamsError(n);
  }
}

/// Enablement: a new account key wrapped under the passphrase and a new
/// recovery key. Returns the record for the server, the device key and the
/// recovery key text to show once.
({KeyRecord record, Uint8List key, String recoveryKey}) createKeyRecord(
  String passphrase, {
  int iterations = pbkdf2Iterations,
}) {
  if (passphrase.length < minPassphraseLength) {
    throw ArgumentError('the passphrase must have at least $minPassphraseLength characters');
  }
  final dek = generateAccountKey();
  final salt = randomSalt();
  final recovery = generateRecoveryBytes();
  final record = KeyRecord(
    version: 1,
    kdf: kdfPbkdf2Sha256,
    salt: b64url(salt),
    iterations: iterations,
    wrappedByPassphrase: wrapAccountKey(dek, derivePassphraseKey(passphrase, salt, iterations)),
    wrappedByRecovery: wrapAccountKey(dek, deriveRecoveryKey(recovery)),
  );
  final recoveryKey = formatRecoveryKey(recovery);
  return (record: record, key: dek, recoveryKey: recoveryKey);
}

Uint8List unlockWithPassphrase(KeyRecord record, String passphrase) {
  if (record.kdf != kdfPbkdf2Sha256) {
    throw ArgumentError('unsupported key derivation ${record.kdf}; update the app');
  }
  checkRecordParams(record);
  final kek = derivePassphraseKey(passphrase, fromB64url(record.salt), record.iterations);
  return unwrapAccountKey(record.wrappedByPassphrase, kek);
}

Uint8List unlockWithRecoveryKey(KeyRecord record, String recoveryKey) {
  final raw = parseRecoveryKey(recoveryKey);
  return unwrapAccountKey(record.wrappedByRecovery, deriveRecoveryKey(raw));
}

/// Passphrase change: re-wrap the same account key under a new passphrase and
/// a new salt; content is not re-encrypted and the recovery wrap is kept.
KeyRecord rewrapWithPassphrase(
  KeyRecord record,
  String currentPassphrase,
  String newPassphrase, {
  int iterations = pbkdf2Iterations,
}) {
  if (newPassphrase.length < minPassphraseLength) {
    throw ArgumentError('the passphrase must have at least $minPassphraseLength characters');
  }
  final dek = unlockWithPassphrase(record, currentPassphrase);
  final salt = randomSalt();
  return KeyRecord(
    version: record.version + 1,
    kdf: kdfPbkdf2Sha256,
    salt: b64url(salt),
    iterations: iterations,
    wrappedByPassphrase: wrapAccountKey(dek, derivePassphraseKey(newPassphrase, salt, iterations)),
    wrappedByRecovery: record.wrappedByRecovery,
  );
}

/// Forgotten passphrase: the recovery key unwraps the account key, which is
/// re-wrapped under a new passphrase and a new recovery key (the old one stops
/// working).
({KeyRecord record, Uint8List key, String recoveryKey}) resetWithRecoveryKey(
  KeyRecord record,
  String recoveryKey,
  String newPassphrase, {
  int iterations = pbkdf2Iterations,
}) {
  if (newPassphrase.length < minPassphraseLength) {
    throw ArgumentError('the passphrase must have at least $minPassphraseLength characters');
  }
  final dek = unlockWithRecoveryKey(record, recoveryKey);
  final salt = randomSalt();
  final recovery = generateRecoveryBytes();
  final next = KeyRecord(
    version: record.version + 1,
    kdf: kdfPbkdf2Sha256,
    salt: b64url(salt),
    iterations: iterations,
    wrappedByPassphrase: wrapAccountKey(dek, derivePassphraseKey(newPassphrase, salt, iterations)),
    wrappedByRecovery: wrapAccountKey(dek, deriveRecoveryKey(recovery)),
  );
  return (record: next, key: dek, recoveryKey: formatRecoveryKey(recovery));
}

// ---- content values ----

/// The additional authenticated data binding a value to where it belongs.
Uint8List bindingOf(String entity, String entityId, String field) =>
    utf8Bytes('$entity\u0000$entityId\u0000$field');

/// Encrypt one content value. [nonce] is for known-answer tests only;
/// production calls always draw a fresh random one.
String encryptValue(
  Uint8List key,
  String entity,
  String entityId,
  String field,
  String plaintext, {
  Uint8List? nonce,
}) {
  final iv = nonce ?? randomBytes(_nonceBytes);
  if (iv.length != _nonceBytes) throw ArgumentError('nonce must be 12 bytes');
  final ct = _aesGcm(key, iv, bindingOf(entity, entityId, field), utf8Bytes(plaintext), encrypt: true);
  return prefixV1 + b64url(Uint8List.fromList([...iv, ...ct]));
}

/// Decrypt one content value; throws DecryptError when it is not authentic
/// for this key and location.
String decryptValue(
  Uint8List key,
  String entity,
  String entityId,
  String field,
  String value,
) {
  if (!value.startsWith(prefixV1)) {
    throw DecryptError('unknown ciphertext format; update the app');
  }
  Uint8List raw;
  try {
    raw = fromB64url(value.substring(prefixV1.length));
  } catch (_) {
    throw DecryptError();
  }
  if (raw.length < _nonceBytes + 16) throw DecryptError();
  try {
    final pt = _aesGcm(
      key,
      raw.sublist(0, _nonceBytes),
      bindingOf(entity, entityId, field),
      raw.sublist(_nonceBytes),
      encrypt: false,
    );
    return utf8.decode(pt);
  } catch (_) {
    throw DecryptError();
  }
}

/// UTF-8 length of a string, for the plaintext size check.
int byteLength(String s) => utf8Bytes(s).length;

// ---- attachment files (OpenSpec attachments, design D8) ----

const String fileMagic = 'OTAT1';
const int fileChunk = 1 << 20;
const int _fileHeader = 17;
const int _tagBytes = 16;

Uint8List _fileNonce(Uint8List prefixBytes, int index, bool finalChunk) {
  if (index >= 1 << 24) throw ArgumentError('file too large for the envelope');
  final n = Uint8List(_nonceBytes);
  n.setRange(0, 8, prefixBytes);
  n[8] = (index >> 16) & 0xff;
  n[9] = (index >> 8) & 0xff;
  n[10] = index & 0xff;
  n[11] = finalChunk ? 1 : 0;
  return n;
}

Uint8List _fileAad(String id, Uint8List header) =>
    Uint8List.fromList([...utf8Bytes('attachment\u0000$id\u0000'), ...header]);

/// Encrypt a file for an attachment: a header and AES-GCM chunks. The id is
/// bound into every chunk; the last chunk is marked final. [prefixBytes] and
/// [chunkSize] are for known-answer tests only.
Uint8List encryptFile(
  Uint8List key,
  String id,
  Uint8List file, {
  Uint8List? prefixBytes,
  int chunkSize = fileChunk,
}) {
  final prefix = prefixBytes ?? randomBytes(8);
  final header = Uint8List(_fileHeader);
  header.setRange(0, 5, utf8Bytes(fileMagic));
  final bd = ByteData(4)..setUint32(0, chunkSize);
  header.setRange(5, 9, bd.buffer.asUint8List());
  header.setRange(9, 17, prefix);
  final aad = _fileAad(id, header);
  final parts = <int>[...header];
  for (var i = 0;; i++) {
    final end = min((i + 1) * chunkSize, file.length);
    final finalChunk = end == file.length;
    final plain = file.sublist(i * chunkSize, end);
    parts.addAll(_aesGcm(key, _fileNonce(prefix, i, finalChunk), aad, plain, encrypt: true));
    if (finalChunk) break;
  }
  return Uint8List.fromList(parts);
}

/// Open an attachment envelope chunk by chunk. Throws DecryptError for a
/// wrong key or id, a reordered, altered or missing chunk, or a truncated file.
Uint8List decryptFile(Uint8List key, String id, Uint8List envelope) {
  if (envelope.length < _fileHeader + _tagBytes) throw DecryptError();
  final header = envelope.sublist(0, _fileHeader);
  if (utf8.decode(header.sublist(0, 5)) != fileMagic) {
    throw DecryptError('unknown file format; update the app');
  }
  final chunkSize = ByteData.sublistView(header, 5, 9).getUint32(0);
  if (chunkSize == 0) throw DecryptError();
  final prefix = header.sublist(9, _fileHeader);
  final aad = _fileAad(id, header);
  final sealed = chunkSize + _tagBytes;
  final body = envelope.length - _fileHeader;
  final count = max(1, (body + sealed - 1) ~/ sealed);
  final parts = <int>[];
  for (var i = 0; i < count; i++) {
    final start = _fileHeader + i * sealed;
    final chunk = envelope.sublist(start, min(start + sealed, envelope.length));
    if (chunk.length < _tagBytes) throw DecryptError();
    try {
      parts.addAll(_aesGcm(key, _fileNonce(prefix, i, i == count - 1), aad, chunk, encrypt: false));
    } catch (_) {
      throw DecryptError();
    }
  }
  return Uint8List.fromList(parts);
}

// ---- the content-value layer (e2eeEnvelope.ts) ----

/// Families of content fields named by a prefix. Only string values of
/// `fields.<id>` are encrypted; numbers and checkboxes stay plaintext.
const Map<String, List<String>> contentPrefixes = {
  'task': ['fields.', 'appends.'],
  'note': ['appends.'],
};

/// Content values that are objects on the device and one encrypted JSON
/// string on the wire.
const Map<String, List<String>> _objectContent = {
  'task': ['origin', 'location'],
  'place': ['geo'],
};

bool isContentField(String entity, String field) {
  if (opContentFields[entity]?.contains(field) ?? false) return true;
  return contentPrefixes[entity]?.any((p) => field.startsWith(p) && field.length > p.length) ?? false;
}

bool _isObjectContent(String entity, String field) =>
    _objectContent[entity]?.contains(field) ?? false;

/// The plaintext a content value encrypts as: a string as it is, an
/// object-valued field as its JSON. null, numbers, booleans and a string in an
/// object-valued field give null: nothing to encrypt.
String? contentToString(String entity, String field, Object? value) {
  if (_isObjectContent(entity, field)) {
    return value is Map ? jsonEncode(value) : null;
  }
  return value is String ? value : null;
}

/// The device value of decrypted plaintext: the object for an object-valued
/// field, else the string.
Object? contentFromString(String entity, String field, String plaintext) {
  if (!_isObjectContent(entity, field)) return plaintext;
  try {
    final v = jsonDecode(plaintext);
    return v is Map ? v : plaintext;
  } catch (_) {
    return plaintext;
  }
}

/// The wire value of one op value for the personal scope of an encrypted
/// account: an envelope for non-empty content, the value itself otherwise.
Object? sealValue(Uint8List key, String entity, String entityId, String field, Object? value) {
  if (!isContentField(entity, field) || isEnvelope(value)) return value;
  final text = contentToString(entity, field, value);
  return (text != null && text.isNotEmpty)
      ? encryptValue(key, entity, entityId, field, text)
      : value;
}

/// The device value of a wire value: decrypted when it is an envelope
/// (throws DecryptError when it is not authentic).
Object? openValue(Uint8List key, String entity, String entityId, String field, Object? value) {
  if (!isEnvelope(value)) return value;
  return contentFromString(entity, field, decryptValue(key, entity, entityId, field, value as String));
}
